import java.util.*; class Solution { static class Editor { private final List<String> values=new ArrayList<>(); private final Deque<Runnable> undo=new ArrayDeque<>(); void add(String value){String clean=value.trim(); if(clean.isEmpty())throw new IllegalArgumentException("value"); values.add(clean); undo.push(() -> values.remove(values.size()-1));} void undo(){if(!undo.isEmpty())undo.pop().run();} List<String> values(){return List.copyOf(values);} } }
